fun owner(tokens: TreeMap<Long, String>, keyPosition: Long): String =
    // the first token at or after the key; past the top of the ring, wrap to the first token
    (tokens.ceilingEntry(keyPosition) ?: tokens.firstEntry()).value

fun replicas(tokens: TreeMap<Long, String>, keyPosition: Long, n: Int): List<String> {
    val want = minOf(n, tokens.values.toSet().size)
    val found = LinkedHashSet<String>()
    // clockwise from the key to the top, then from the bottom: each token at most once
    for (node in tokens.tailMap(keyPosition, true).values.asSequence() + tokens.values.asSequence()) {
        found += node
        if (found.size == want) break
    }
    return found.toList()
}
